import test from 'node:test';
import assert from 'node:assert/strict';
import {testServer} from './helpers.js';
import {createIssue} from '../src/modules/work/issues.js';
async function fixture(run){const server=await testServer();try{const api=server.agent(),user=(await api('POST','/auth/signup',{name:'Tree owner',email:'tree@example.test',password:'correct-horse-battery'})).data.user,org=(await api('POST','/orgs',{name:'Tree org'})).data.organization,project=(await api('POST','/orgs/'+org.id+'/projects',{key:'TREE',name:'Tree project'})).data.project;await run({server,api,user,org,project,create:body=>createIssue(server.ctx,{user},project.id,body)});}finally{await server.close();}}
test('canonical root and child pages enumerate more than 200 records without mixing levels',()=>fixture(async({api,project,create})=>{
  const root=create({title:'Matching root',priority:4}),roots=[root],children=[];
  for(let n=0;n<203;n++){roots.push(create({title:'Root '+n}));children.push(create({title:'Child '+n,parentId:root.id}));}
  create({title:'Grandchild',parentId:children[0].id});
  for(const [parent,expected] of [['null',roots],[root.id,children]]){let cursor=null;const ids=[];do{const response=await api('GET','/projects/'+project.id+'/issues?'+new URLSearchParams({parentId:parent,limit:20,...(cursor?{cursor}:{})}));assert.equal(response.status,200);ids.push(...response.data.items.map(item=>item.id));cursor=response.data.nextCursor;}while(cursor);assert.equal(ids.length,expected.length);assert.deepEqual(new Set(ids),new Set(expected.map(item=>item.id)));}
  const match=await api('GET','/projects/'+project.id+'/issues?parentId=null&q=Matching&priority=4');assert.deepEqual(match.data.items.map(item=>item.id),[root.id]);
  assert.equal((await api('GET','/projects/'+project.id+'/issues?parentId='+children[0].id)).data.items[0].title,'Grandchild');
}));
test('root and child filters use canonical guest grants and work-only token scope before paging',()=>fixture(async({server,api,project,org,create})=>{
  const root=create({title:'Visible root'});create({title:'Visible child',parentId:root.id});
  const guest=server.agent(),person=(await guest('POST','/auth/signup',{name:'Tree reader',email:'tree-guest@example.test',password:'correct-horse-battery'})).data.user;
  await api('POST','/orgs/'+org.id+'/members',{userId:person.id,role:'guest'});
  for(const parent of ['null',root.id])assert.equal((await guest('GET','/projects/'+project.id+'/issues?parentId='+parent)).status,403);
  await api('POST','/projects/'+project.id+'/guests',{userId:person.id});
  for(const parent of ['null',root.id])assert.equal((await guest('GET','/projects/'+project.id+'/issues?parentId='+parent)).data.items.length,1);
  const token=(await api('POST','/tokens',{name:'Work tree',scopes:['project:read']})).data.token;
  assert.equal((await api('GET','/projects/'+project.id+'/issues?parentId=null',undefined,{authorization:'Bearer '+token})).status,200);
  await api('DELETE','/projects/'+project.id+'/guests/'+person.id);assert.equal((await guest('GET','/projects/'+project.id+'/issues?parentId='+root.id)).status,403);
}));

import {createIssuePages} from './issue-paging.js';
export const hierarchyAccessLost = page => [401,403,404].includes(page?.error?.status);
export function createIssueHierarchy(load,notify=()=>{}) {
  const pages=new Map(),expanded=new Set();
  let disposed=false,focus=null,wanted=null,focusVersion=0;
  const empty={items:[],cursor:null,loading:true,busy:false,error:null};
  function rows() {
    const result=[],stack=[{parent:null,level:1}];
    while(stack.length) {
      const entry=stack.pop();
      if(entry.issue){result.push(entry);if(expanded.has(entry.issue.id))stack.push({parent:entry.issue.id,level:entry.level+1});continue;}
      const page=pages.get(entry.parent)?.snapshot();
      if(!page||hierarchyAccessLost(page))continue;
      for(let index=page.items.length-1;index>=0;index--)stack.push({issue:page.items[index],parent:entry.parent,level:entry.level});
    }
    return result;
  }
  function snapshot(){return {root:pages.get(null)?.snapshot()??empty,branches:Object.fromEntries([...pages].filter(([id])=>id!==null).map(([id,page])=>[id,page.snapshot()])),expanded:[...expanded],rows:rows(),focus,focusVersion};}
  function publish(){if(disposed)return;const visible=rows();if(!visible.some(row=>row.issue.id===focus)){const next=visible[0]?.issue.id??null;if(focus!==next){focus=next;focusVersion++;}}notify(snapshot());}
  function move(id){focus=id;focusVersion++;publish();}
  function owner(parent) {
    if(!pages.has(parent)){
      const page=createIssuePages(cursor=>load(parent,cursor),state=>{
        if(disposed||pages.get(parent)!==page)return;
        if(wanted?.parent===parent&&!state.loading&&!state.busy){const next=state.items.find(item=>!wanted.before.has(item.id));wanted=null;if(next){focus=next.id;focusVersion++;}}
        publish();
      });
      pages.set(parent,page);
    }
    return pages.get(parent);
  }
  function collapse(id){
    const visible=rows(),index=visible.findIndex(row=>row.issue.id===id),descendants=new Set();
    for(let n=index+1;n<visible.length&&visible[n].level>visible[index].level;n++)descendants.add(visible[n].issue.id);
    for(const key of [id,...descendants]){expanded.delete(key);pages.get(key)?.dispose();pages.delete(key);}
    if(wanted&&(wanted.parent===id||descendants.has(wanted.parent)))wanted=null;
    if(descendants.has(focus))move(id);else publish();
  }
  async function expand(id,enter=false){
    if(expanded.has(id)){if(enter){const child=pages.get(id)?.snapshot().items[0];if(child)move(child.id);}return;}
    expanded.add(id);const page=owner(id);if(enter)wanted={parent:id,before:new Set()};publish();await page.reload();
  }
  async function more(parent){const page=pages.get(parent);if(!page||page.snapshot().busy||!page.snapshot().cursor)return;wanted={parent,before:new Set(page.snapshot().items.map(item=>item.id))};await page.more();}
  function key(id,key){
    const visible=rows(),index=visible.findIndex(row=>row.issue.id===id);if(index<0)return false;
    if(key==='ArrowDown')move(visible[Math.min(index+1,visible.length-1)].issue.id);
    else if(key==='ArrowUp')move(visible[Math.max(index-1,0)].issue.id);
    else if(key==='Home')move(visible[0].issue.id);
    else if(key==='End')move(visible.at(-1).issue.id);
    else if(key==='ArrowRight')expand(id,true);
    else if(key==='ArrowLeft'){if(expanded.has(id))collapse(id);else if(visible[index].parent)move(visible[index].parent);}
    else return false;
    return true;
  }
  return {snapshot,load:()=>owner(null).reload(),expand,collapse,more,key,focus:move,
    reload(){for(const page of pages.values())page.dispose();pages.clear();expanded.clear();wanted=null;focus=null;publish();return owner(null).reload();},
    dispose(){disposed=true;wanted=null;for(const page of pages.values())page.dispose();pages.clear();expanded.clear();}};
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {createIssueHierarchy} from '../src/pages/work/issue-hierarchy.js';
const page=(items,nextCursor=null)=>({items:items.map(id=>({id})),nextCursor});
const deferred=()=>{let resolve,reject;const promise=new Promise((a,b)=>{resolve=a;reject=b;});return {promise,resolve,reject};};
test('hierarchy loads only roots until expanded and each child cursor has independent ownership',async()=>{
  const calls=[],slow=deferred();const tree=createIssueHierarchy(async(parent,cursor)=>{calls.push([parent,cursor]);if(parent==='a'&&cursor)return slow.promise;return parent===null?page(['a','b'],'roots'):parent==='a'?page(['a1'],'children'):page(['b1']);});
  await tree.load();assert.deepEqual(calls,[[null,null]]);await tree.expand('a');await tree.expand('b');
  const pending=tree.more('a');await tree.more('a');assert.equal(calls.filter(([id,c])=>id==='a'&&c).length,1);
  assert.deepEqual(tree.snapshot().rows.map(row=>row.issue.id),['a','a1','b','b1']);slow.resolve(page(['a2']));await pending;
  assert.deepEqual(tree.snapshot().branches.a.items.map(item=>item.id),['a1','a2']);assert.equal(tree.snapshot().root.cursor,'roots');assert.equal(tree.snapshot().focus,'a2');
});
test('collapse disposes delayed children and re-expansion owns a fresh request',async()=>{
  const slow=deferred();let children=0;const tree=createIssueHierarchy(parent=>parent===null?Promise.resolve(page(['a'])):++children===1?slow.promise:Promise.resolve(page(['fresh'])));
  await tree.load();const pending=tree.expand('a',true);tree.collapse('a');await tree.expand('a');slow.resolve(page(['stale'],'wrong'));await pending;
  assert.deepEqual(tree.snapshot().branches.a.items.map(item=>item.id),['fresh']);assert.equal(tree.snapshot().branches.a.cursor,null);
});
test('tree arrows home and end follow visible depth and collapse restores descendant focus',async()=>{
  const tree=createIssueHierarchy(async parent=>parent===null?page(['a','b']):parent==='a'?page(['c']):page(['d']));
  await tree.load();await tree.expand('a',true);assert.equal(tree.snapshot().focus,'c');await tree.expand('c',true);assert.equal(tree.snapshot().focus,'d');
  tree.key('d','ArrowLeft');assert.equal(tree.snapshot().focus,'c');tree.collapse('a');assert.equal(tree.snapshot().focus,'a');
  tree.key('a','End');assert.equal(tree.snapshot().focus,'b');tree.key('b','Home');assert.equal(tree.snapshot().focus,'a');tree.key('a','ArrowDown');assert.equal(tree.snapshot().focus,'b');tree.key('b','ArrowUp');assert.equal(tree.snapshot().focus,'a');assert.equal(tree.key('a','Tab'),false);
});
test('late old project success and failure cannot notify or change a replacement tree',async()=>{
  const slow=deferred(),seen=[];const old=createIssueHierarchy(()=>slow.promise,state=>seen.push(state));const pending=old.load();old.dispose();const count=seen.length;
  const current=createIssueHierarchy(async()=>page(['current']));await current.load();slow.reject(Object.assign(new Error('Old denial'),{status:403}));await pending;
  assert.equal(seen.length,count);assert.equal(current.snapshot().focus,'current');assert.equal(current.snapshot().root.error,null);
});
test('current access denial hides previously visible children and exposes a deliberate reload state',async()=>{
  let count=0;const tree=createIssueHierarchy(async parent=>parent===null?page(['a']):++count===1?page(['secret'],'next'):Promise.reject(Object.assign(new Error('Grant removed'),{status:403})));
  await tree.load();await tree.expand('a');await tree.more('a');assert.deepEqual(tree.snapshot().rows.map(row=>row.issue.id),['a']);assert.equal(tree.snapshot().branches.a.error.status,403);assert.equal(tree.snapshot().branches.a.busy,false);
});
test('reload drops every old branch and same-cursor failures retain deliberate error custody',async()=>{
  const tree=createIssueHierarchy(async(parent,cursor)=>parent===null?page(['a'],'same'):page(['child']));await tree.load();await tree.expand('a');await tree.more(null);
  assert.match(tree.snapshot().root.error.message,/same page cursor/);await tree.reload();assert.deepEqual(tree.snapshot().expanded,[]);assert.deepEqual(tree.snapshot().branches,{});
});
